/* Пазурі Смерті: лапи як вбудована зброя, з урахуванням «Залізних кулаків» */
function syncClaws_old(st){
  const isClaw = st.species==='claw';
  st.weapons = st.weapons.filter(w=>!w.claw || isClaw);
  if(!isClaw) return;
  const dmg = (st.perks||[]).some(p=>p.n==='Залізні кулаки') ? '2d6' : '1d10';
  let w = st.weapons.find(x=>x.claw);
  if(!w){ w = st.weapons.find(x=>x.n==='Пазурі'); if(w) w.claw=true; }
  if(!w){ w={n:'Пазурі', d:dmg, h:false, en:'', note:'', claw:true}; st.weapons.unshift(w); }
  w.n='Пазурі'; w.d=dmg; w.en=''; w.h=false; w.note='ближній бій, ігнорують 1 броні'+(dmg==='2d6'?'; «Залізні кулаки»':'');
  const i=st.weapons.indexOf(w); if(i>0){ st.weapons.splice(i,1); st.weapons.unshift(w); }
}

