function aspFits(text, sp, gender){
  const s=ASP_SP[text]; if(s && sp && !s.includes(SP_CODE[sp])) return false;
  const g=ASP_GENDER[text]; if(g && gender && g!==gender) return false;
  const e=ASP_EXTRA.find(x=>x[3]===text); if(e && sp && e[2]!=='*' && !e[2].includes(SP_CODE[sp])) return false;
  return true;
}
function aspPool(arch, i, sp, gender, feats){
  const psi=(feats||[]).includes('Псионік');
  const a=ARCH[arch]; if(!a) return [];
  const book=a.asp[i].filter(t=>aspFits(t, sp, gender));
  const ex=ASP_EXTRA.filter(e=>e[0]===i && (e[1]==='*' || e[1].split(' ').some(k=>k==='ψ' ? psi : ASP_A[k]===arch)) && (e[2]==='*' || e[2].includes(SP_CODE[sp]||'h'))).map(e=>e[3]);
  return [...book, ...ex];
}

