function noteIgnore(t){ t=String(t||'').toLowerCase(); if(/ігнору[а-яіїєґ]*\s+(фізичну\s+)?броню|повністю ігнору/.test(t)) return 99; const m=t.match(/ігнору[а-яіїєґ]*\s+(\d+)\s+(фізичн[а-яіїєґ]*\s+)?брон/); return m?+m[1]:0; }
function gunProps(w){
  if(!gunsOn() || !w || w.claw || w.auto==='psi') return '';
  return [w.r?(w.r==='melee'?'ближній бій':w.r==='max'?'дальність макс.':'дальність '+w.r):'', w.r==='melee'&&w.rof==='melee'?'':(GUN_ROF_N[w.rof]||''), w.sharp?'гостра':'', modList(w).length?'мод.: '+modList(w).map(m=>m.n.trim()).join(', '):''].filter(Boolean).join('; ');
}
function armorNote(a){ return [a.note, gunsOn()&&modList(a).length?'мод.: '+modList(a).map(m=>m.n.trim()).join(', '):''].filter(Boolean).join('; '); }

/* Опис речі з довідника для предметів із випадкової генерації */
