/* ===== Свої перки та особливості ===== */
function perkDef(p){ return p && p.custom ? {n:p.n, c:'Свій перк', d:p.d||'', rt:'', custom:true} : PERK[p.n]; }
function customFeat(st, fn){ return (st.customFeats||[]).find(x=>x.n===fn) || null; }
function featDef(st, fn){ if(FEAT[fn]) return FEAT[fn]; const c=customFeat(st,fn); return c ? {n:c.n, c:'Своя особливість', d:c.d||'', custom:true, extra:!!c.extra} : null; }
function countedPerks(st){ return st.perks.filter(p=>!(p.custom && p.extra)).length; }
function countedFeats(st){ return st.feats.filter(fn=>{ const c=customFeat(st,fn); return !(c && c.extra); }).length; }
function officialName(n){ const l=String(n||'').trim().toLowerCase(); return PERKS.some(p=>p.n.toLowerCase()===l) || FEATS.some(f=>f.n.toLowerCase()===l); }

